/// One version's table.
pub struct Ops {
    pub version: (u8, u8),
    /// Opcode names; empty for unused opcodes.
    pub names: [&'static str; 256],
    /// Inline cache code units after each opcode (3.11+).
    pub caches: [u8; 256],
    /// `K_*` argument kinds.
    pub kinds: [u8; 256],
    /// Opcodes at or above this take an argument (before 3.6).
    pub have_argument: u8,
    pub extended_arg: u8,
    pub cmp_op: &'static [&'static str],
}

